function toast(message, error = false) { const el = $('#toast'); el.textContent = message; el.className = error ? 'error' : ''; el.style.display = 'block'; clearTimeout(toast.timer); toast.timer = setTimeout(() => el.style.display = 'none', 5500); }
const pretty = value => JSON.stringify(value, null, 2);
