function btn(text, action, primary = false, extra = '') { return `<button class="btn ${primary ? 'primary' : ''}" data-action="${action}" ${state.busy ? 'disabled' : ''} ${extra}>${text}</button>`; }
function field(title, control, hint = '') { return `<label class="field"><span>${title}</span>${control}${hint ? `<small>${hint}</small>` : ''}</label>`; }
function select(name, options, selected) { return `<select name="${name}">${options.map(x => `<option value="${escape(typeof x === 'string' ? x : x.value)}" ${(typeof x === 'string' ? x : x.value) === selected ? 'selected' : ''}>${escape(typeof x === 'string' ? label(x) : x.label)}</option>`).join('')}</select>`; }
function input(name, value = '', placeholder = '') { return `<input class="input" name="${name}" value="${escape(value)}" placeholder="${escape(placeholder)}" autocomplete="off">`; }
