  state.configDrafts[id] = Object.fromEntries([...document.querySelectorAll('.main [name]')].filter(el => ['INPUT','SELECT','TEXTAREA'].includes(el.tagName)).map(el => [el.name, el.type === 'checkbox' ? {checked:el.checked} : {value:el.value}]));
