    const {jobId} = await api(`/subscriptions/${provider}/${operation}`,{method:'POST',body:operation === 'install' ? {consent:true} : {device}});
    state.job = {id:jobId,kind:operation,provider,status:'running',progressMessages:[]}; state.subscriptionJob = state.job; render();
    let job;
    do { await new Promise(resolve => setTimeout(resolve,650)); job = await api(`/jobs/${jobId}`); state.job = job; state.subscriptionJob = job; renderSubscriptionSurfaces(); } while (['running','cancelling'].includes(job.status));
    state.job = null; state.busy = false; await loadSubscriptions(provider); render();
    if (job.status === 'failed') toast(job.error || 'Setup did not complete. Follow the provider instructions and try again.',true);
    else if (job.status === 'cancelled') toast('Setup cancelled.');
    else if (job.result?.terminalRequired) toast('Finish this provider login in your terminal. The command is shown in setup.',true);
